const MONTHS = [["January","يناير"],["February","فبراير"],["March","مارس"],["April","أبريل"],["June","يونيو"],["July","يوليو"],["August","أغسطس"],["September","سبتمبر"],["October","أكتوبر"],["November","نوفمبر"],["December","ديسمبر"],["May","مايو"],["Sept","سبتمبر"],["Jan","يناير"],["Feb","فبراير"],["Mar","مارس"],["Apr","أبريل"],["Jun","يونيو"],["Jul","يوليو"],["Aug","أغسطس"],["Sep","سبتمبر"],["Oct","أكتوبر"],["Nov","نوفمبر"],["Dec","ديسمبر"]];
export function arDate(s) {
  if (!s || typeof s !== "string") return s;
  let t = s;
  t = t.replace(/Week of/g, "أسبوع").replace(/Friday,?/g, "الجمعة").replace(/Monday/g, "الاثنين");
  t = t.replace(/Late next week/g, "أواخر الأسبوع المقبل").replace(/Next week/g, "الأسبوع المقبل").replace(/Next review/g, "المراجعة القادمة");
  t = t.replace(/^By /g, "بحلول ").replace(/\bLate\b/g, "أواخر");
  for (const [en, ar] of MONTHS) t = t.replace(new RegExp("\\b" + en + "\\b", "g"), ar);
  t = t.replace(/\bTBD\b/g, "TBD");
  return t;
}

